/* Pane 모델 전환 카드의 문구 (docs/plan/261026-agent-chat-grammar.md §4).
   서버(`workflow/panes.rs`)가 pane 의 agent 모델이 고른 모델과 다르다고 본 메시지는 `ask` 를 달고
   큐에서 기다린다. 수락 = 그 agent 를 닫고 새 세션으로 연다, 취소 = 지금 agent 에 그대로 보낸다. */

/** What the server read the pane's agent to run on (`Running`). */
export type PaneRunning = { agent: string; model?: string; effort?: string };
/** The composer's chosen model (`RoleModel`). */
export type ChosenModel = { harness: string; model: string; effort: string };

/** `sonnet-5-5 · high`: claude ids lose their `claude-` prefix, pi keeps `provider/id`. */
export function modelLabel(model?: string, effort?: string): string {
	const name = model ? model.replace(/^claude-/, "") : "unknown model";
	return effort ? `${name} · ${effort}` : name;
}

/** The card's question for pane `slot` (0 = no number on this device). */
export function switchQuestion(slot: number, running: PaneRunning, chosen: ChosenModel | null | undefined): string {
	const pane = slot > 0 ? `Pane ${slot}` : "This pane";
	const now = `${running.agent} (${modelLabel(running.model, running.effort)})`;
	const next = chosen ? `${chosen.harness} ${modelLabel(chosen.model, chosen.effort)}` : "the chosen model";
	return `${pane} runs ${now}. Close it and open ${next} in a new session? The conversation does not carry over.`;
}

