/**
 * Task name from a harness terminal title, or null when the title is only the app
 * (nothing started yet).
 *
 * Claude prefixes a spinner glyph (`✳`, braille) and shows `Claude Code` while idle.
 * Pi's title is `{app} - {session} - {folder}`; the session may itself contain ` - `.
 */

const CLAUDE_IDLE = "Claude Code";

export function taskTitle(harness: "claude" | "pi", title: string): string | null {
	const text = title.trim();
	if (!text) return null;
	return harness === "claude" ? claudeTask(text) : piTask(text);
}

/** Drop one leading spinner glyph and the space after it. A word stays put. */
function stripSpinner(title: string): string {
	const space = title.indexOf(" ");
	if (space <= 0) return title;
	const head = title.slice(0, space);
	if ([...head].length !== 1) return title;
	const code = head.codePointAt(0);
	if (code === undefined || isWord(code)) return title;
	return title.slice(space + 1).trim();
}

function isWord(code: number): boolean {
	return (code >= 0x30 && code <= 0x39) || (code >= 0x41 && code <= 0x5a) || (code >= 0x61 && code <= 0x7a);
}

function claudeTask(title: string): string | null {
	const topic = stripSpinner(title);
	if (!topic || topic === CLAUDE_IDLE) return null;
	return topic;
}

function piTask(title: string): string | null {
	const parts = title.split(" - ");
	if (parts.length < 3) return null;
	const session = parts.slice(1, -1).join(" - ").trim();
	return session || null;
}
